import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const PeriodTrackerPage = () => {
  const navigate = useNavigate();
  const [lastPeriodDate, setLastPeriodDate] = useState("");
  const [cycleLength, setCycleLength] = useState(28);
  const [nextPeriodDate, setNextPeriodDate] = useState("");
  const [currentPhase, setCurrentPhase] = useState("");

  // Function to calculate next period and current phase
  const calculatePeriodDetails = () => {
    if (!lastPeriodDate || cycleLength < 21 || cycleLength > 35) {
      alert("Please enter a valid last period date and cycle length (21-35 days).");
      return;
    }

    const lastDate = new Date(lastPeriodDate);
    const nextDate = new Date(lastDate);
    nextDate.setDate(lastDate.getDate() + cycleLength);

    setNextPeriodDate(nextDate.toDateString());

    // Calculate current phase
    const today = new Date();
    const daysSinceLastPeriod = Math.floor((today - lastDate) / (1000 * 60 * 60 * 24));

    let phase = "";
    if (daysSinceLastPeriod >= 0 && daysSinceLastPeriod <= 5) {
      phase = "Menstrual Phase (Your period days)";
    } else if (daysSinceLastPeriod > 5 && daysSinceLastPeriod <= 14) {
      phase = "Follicular Phase (Body preparing for ovulation)";
    } else if (daysSinceLastPeriod > 14 && daysSinceLastPeriod <= 16) {
      phase = "Ovulation Phase (Most fertile days)";
    } else {
      phase = "Luteal Phase (Hormonal changes before next period)";
    }

    setCurrentPhase(phase);
  };

  const handleBackToHome = () => {
    navigate("/", { replace: true });
  };

  return (
    <div className="period-tracker">
      <h1>Period Tracker</h1>
      <p>Track your cycle and understand your body's phases.</p>

      <div className="tracker-form">
        <label>Last Period Date:</label>
        <input 
          type="date" 
          value={lastPeriodDate} 
          onChange={(e) => setLastPeriodDate(e.target.value)} 
        />

        <label>Cycle Length (days):</label>
        <input 
          type="number" 
          value={cycleLength} 
          onChange={(e) => setCycleLength(Number(e.target.value))} 
          min="21" max="35"
        />

        <button className="pink-button" onClick={calculatePeriodDetails}>
          Track Period
        </button>
      </div>

      {nextPeriodDate && (
        <div className="results">
          <h3>Next Period Date: {nextPeriodDate}</h3>
          <h3>Current Phase: {currentPhase}</h3>
        </div>
      )}

      <div className="health-tips">
        <h2>Menstrual Health Tips</h2>
        <ul>
          <li>Stay hydrated and maintain a balanced diet.</li>
          <li>Exercise regularly to reduce cramps.</li>
          <li>Track your mood and symptoms for better cycle management.</li>
          <li>Consult a doctor if you experience irregular cycles.</li>
        </ul>
      </div>

      <div className="button-container">
        <button className="pink-button" onClick={handleBackToHome}>
          Back to Home
        </button>
      </div>
    </div>
  );
};

export default PeriodTrackerPage;
